func (s *Store) CheckPolicy(ctx context.Context, token runtime.Tx, subject v.SubjectBinding, ref v.ContentRef, purpose string, actions []string, now time.Time) (policyRecord *contentdomain.FixturePolicy, policyErr error) {
	tx, err := s.core.SQL(ctx, token, commonOwner(ref.Owner))
	if err != nil {
		return nil, err
	}
	key, _, err := subjectKey(subject)
	if err != nil {
		return nil, err
	}
	var body []byte
	err = tx.QueryRowContext(ctx, `WITH locked_policy AS MATERIALIZED (SELECT body FROM `+s.core.Table("content_fixture_policies")+` WHERE tenant_id=$1 AND owner_id=$2 AND subject_key=$3 AND content_id=$4 AND version=$5 AND purpose=$6 FOR SHARE) SELECT body,clock_timestamp() FROM locked_policy`, ref.Owner.TenantID, ref.Owner.OwnerID, key, ref.ContentID, ref.Version, purpose).Scan(&body, &now)
	if errors.Is(err, sql.ErrNoRows) {
		return nil, nil
	}
	if err != nil {
		return nil, err
	}
	// The MATERIALIZED locked row is obtained before the outer volatile clock
	// projection. Keep clock_timestamp outside LockRows; transaction or statement
	// timestamps, and independent clock CTEs, can precede the actual lock wait.
	var policy contentdomain.FixturePolicy
	if err = json.Unmarshal(body, &policy); err != nil {
		return nil, err
	}
	if policy.Ref.Owner != ref.Owner || policy.Ref.ContentID != ref.ContentID || policy.Ref.Version != ref.Version || policy.Purpose != purpose || !now.Before(policy.ValidUntil) {
		return nil, nil
	}
	match := key
	if !reflect.DeepEqual(policy.Subject, subject) {
		match, _, err = subjectKey(policy.Subject)
		if err != nil {
			return nil, err
		}
	}
	if match != key {
		return nil, nil
	}
	if len(actions) == 0 || len(actions) > 5 {
		return nil, nil
	}
	seen := map[string]bool{}
	for _, action := range actions {
		if seen[action] {
			return nil, nil
		}
		seen[action] = true
		allowed := false
		switch action {
		case "read":
			allowed = policy.Read
		case "process":
			allowed = policy.Process
		case "save":
			allowed = policy.Save
		case "sync":
			allowed = policy.Sync
		case "disclose":
			allowed = policy.Disclose
		}
		if !allowed {
			return nil, nil
		}
	}
	return &policy, nil
}

